import{_ as o,o as a,c as r,a2 as n}from"./chunks/framework.1C62pOns.js";const s="/pro-agent-hub-installer/capturas/es/provedores-detalhe.png",t="/pro-agent-hub-installer/capturas/es/modelos-detalhe.png",v=JSON.parse('{"title":"Proveedores y modelos","description":"","frontmatter":{},"headers":[],"relativePath":"es/interface/provedores-modelos.md","filePath":"es/interface/provedores-modelos.md","lastUpdated":1787856241000}'),i={name:"es/interface/provedores-modelos.md"};function d(l,e,c,p,m,u){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="proveedores-y-modelos" tabindex="-1">Proveedores y modelos <a class="header-anchor" href="#proveedores-y-modelos" aria-label="Permalink to &quot;Proveedores y modelos&quot;">​</a></h1><p>Por aquí se empieza. Un agente sin modelo no se guarda, y un modelo sin proveedor no existe.</p><h2 id="proveedores" tabindex="-1">Proveedores <a class="header-anchor" href="#proveedores" aria-label="Permalink to &quot;Proveedores&quot;">​</a></h2><p><img src="'+s+'" alt="provedores-detalhe"></p><p>Un <strong>proveedor</strong> es de dónde viene la inteligencia: OpenAI, Anthropic, Google o un Ollama corriendo en tu propia máquina. El registro guarda el tipo, la dirección y la clave de API.</p><p><strong>La clave viaja en el archivo de exportación</strong>, cifrada — pero con una clave por defecto que está en el código, lo que protege de la lectura casual y no de alguien decidido. Conviene saberlo antes de mandarle un export a alguien. Ver <a href="/pro-agent-hub-installer/es/interface/administracao#importar-y-exportar">Importar y exportar</a>.</p><p><strong>Ollama no pide clave.</strong> Corre junto a la instalación y la dirección por defecto ya viene rellenada. Es el camino para no depender de un servicio de pago ni mandar datos afuera.</p><h2 id="modelos" tabindex="-1">Modelos <a class="header-anchor" href="#modelos" aria-label="Permalink to &quot;Modelos&quot;">​</a></h2><p><img src="'+t+'" alt="modelos-detalhe"></p><p>Un <strong>modelo</strong> es un modelo concreto de un proveedor — <code>gpt-4o</code> de OpenAI, <code>nomic-embed-text</code> de Ollama. El mismo nombre puede existir en proveedores distintos, y la plataforma los trata como registros separados.</p><p>Dos marcas deciden dónde se puede usar:</p><ul><li><strong>Uso en chat</strong> — puede ser el cerebro de un agente, equipo o planificador.</li><li><strong>Uso en embedding</strong> — puede vectorizar un conocimiento.</li></ul><p>Un modelo de embedding tiene <strong>dimensión</strong>, y tiene que coincidir con la de los vectores ya guardados. Cambiar el modelo de embedding de un conocimiento ya vectorizado exige una recarga completa — la colección se recrea con la nueva dimensión.</p><h3 id="precio-y-límites" tabindex="-1">Precio y límites <a class="header-anchor" href="#precio-y-límites" aria-label="Permalink to &quot;Precio y límites {#precio-y-límites}&quot;">​</a></h3><p>El registro acepta precio por millón de tokens (entrada y salida) y topes de consumo diario y mensual, por tokens o por coste.</p><p><strong>El tope tiene dos etapas</strong>, y vale entender la diferencia antes de configurarlo:</p><ul><li>Al cruzar el <strong>porcentaje de alerta</strong>, la plataforma avisa por correo a los usuarios master y sigue funcionando.</li><li>Al cruzar el <strong>límite</strong>, con <em>bloquear</em> activo, las ejecuciones de ese modelo pasan a rechazarse.</li></ul><p>Sin precio registrado no hay coste que seguir — solo conteo de tokens. El seguimiento está en <a href="/pro-agent-hub-installer/es/interface/administracao#consumo-de-tokens">Consumo de tokens</a>.</p>',18)])])}const h=o(i,[["render",d]]);export{v as __pageData,h as default};
